<?php use Namira\{CallCampaigns,Protocol};view('calls-assets'); ?>
<div class="heading"><div><h1>فراخوان‌های نامیرا</h1><p class="muted">آثار ماندگار، برای روایت شهدا</p></div><a class="outline" href="<?= e(url('account',['section'=>'submissions'])) ?>">ارسال‌های من</a></div>
<form method="get" class="call-search"><input type="hidden" name="page" value="calls"><label class="sr-only" for="call-search">جست‌وجوی فراخوان</label><input id="call-search" name="q" placeholder="جست‌وجوی فراخوان…" value="<?= e(is_string($_GET['q']??null)?$_GET['q']:'') ?>"><button class="primary">جست‌وجو</button></form>
<div class="call-grid"><?php foreach($result['items'] as $card):$card['config']=array_replace(CallCampaigns::defaults(),Protocol::decode($card['criteria']));$open=CallCampaigns::accepting($card); ?><article class="call-card"><?php if($card['poster_asset_id']): ?><a href="<?= e(url('call',['id'=>$card['id']])) ?>"><img class="call-poster" src="<?= e(url('asset',['id'=>$card['poster_asset_id']])) ?>" alt="<?= e($card['title']) ?>" loading="lazy"></a><?php else: ?><div class="call-poster call-poster-placeholder" aria-hidden="true">فراخوان نامیرا</div><?php endif ?><div class="call-card-body"><span class="badge"><?= $open?'در حال دریافت آثار':'دریافت آثار بسته است' ?></span><h2><a href="<?= e(url('call',['id'=>$card['id']])) ?>"><?= e($card['title']) ?></a></h2><p><?= e(mb_substr($card['description'],0,180)) ?></p><small><?= $card['config']['mode']==='competition'?'رقابتی؛ داوری خارج از سامانه':'جمع‌آوری آثار' ?></small><?php if($card['end_at']): ?><p class="hint">پایان دریافت: <span dir="ltr"><?= fa($card['end_at']) ?></span> (ساعت تهران)</p><?php endif ?><a class="primary" href="<?= e(url('call',['id'=>$card['id']])) ?>">جزئیات و شرکت در فراخوان</a></div></article><?php endforeach ?></div>
<?php if(!$result['items']): ?><section class="empty"><h2>فراخوانی برای نمایش نیست</h2><p>فراخوان‌های منتشرشده در این بخش قرار می‌گیرند.</p></section><?php endif ?><?php view('public-pagination',['count'=>$result['count'],'per'=>$result['per'],'page'=>$result['page'],'route'=>'calls','filters'=>['q'=>$_GET['q']??'']]); ?>